import{_ as t,o as s,c as o,j as e,a as _}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/96-“工作上流”与“悠闲下流”的分裂.md","filePath":"books/xialiu-shehui/96-“工作上流”与“悠闲下流”的分裂.md","lastUpdated":1794732511000}'),l={name:"books/xialiu-shehui/96-“工作上流”与“悠闲下流”的分裂.md"};function r(n,a,i,d,p,u){return s(),o("div",null,[...a[0]||(a[0]=[e("h2",{id:"工作上流-与-悠闲下流-的分裂",tabindex:"-1"},[_("“工作上流”与“悠闲下流”的分裂 "),e("a",{class:"header-anchor",href:"#工作上流-与-悠闲下流-的分裂","aria-label":'Permalink to "“工作上流”与“悠闲下流”的分裂"'},"​")],-1),e("p",null,"今天坐电车的时候，有个年轻男子坐在身旁狼吞虎咽地啃着“麦当劳”的汉堡包。这个穿着T恤、懒得刮胡子的年轻人，究竟是靠什么来生活的呢？随意躺倒在街上或是火车站里的年轻人并不少见，而且不是在晚上，而是在白天或者早上。在“扒金窟”的门口，一大早就有年轻人坐在那里等着开门。近来每每看到这样的人，总会不由自主地想这会不会就是所谓的NEET一族？",-1),e("p",null,"他们是否想到过，与自己属于同一世代的年轻人，此刻正穿着西装在工作？也许他们觉得，我就是讨厌过那样的生活。或者反过来，穿着西装工作的年轻人，对自由打工族或NEET一族又会有什么看法呢？或许他们也会觉得，我才不想过那样的生活，或者是我也想过那样的生活？",-1),e("p",null,"在阶级分明的英国，如果说到“我们和他们（us and them）”，那就是指劳动者阶级和统治阶级。而在日本，自由打工族或NEET一族与在大企业里工作的白领阶层，也已经成为类似于“我们和他们”这样的关系了。",-1),e("p",null,"这就产生了一个问题：上流阶层对下流阶层懒散的生活方式究竟能够容忍到何种地步？这样的问题渐渐浮上台面。上流阶层或许已经不再向往下流阶层那种自由自在的生活方式，而是否定那种自甘堕落、毫无责任感的生活方式。",-1)])])}const m=t(l,[["render",r]]);export{h as __pageData,m as default};
